function CatHouseCatCheckPopup:__delete()
    if not isNull(self.go) then
        KTool.SafeDelete(self.go.gameObject)
        self.go = nil
    end
    if next(self.oldShowLoadedScenesState) then
        for identifier, enable in pairs(self.oldShowLoadedScenesState) do
            SceneManagementIns:SetActive(identifier, enable)
        end
    end
    self.oldShowLoadedScenesState = nil
end

