function CatHouseCatCheckPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.oldShowLoadedScenesState = SceneManagementIns:GetShowLoadedScenesState()
        local catHouseMgr = CatHouseMgr:GetInstance()
        while catHouseMgr:GetSceneCo(SceneId) ~= nil do
            cs_coroutine.yield_return()
        end
        ---@type SceneInstance
        local sceneInstance = SceneManagementIns:GetSceneInstance(SceneId)
        local cameraObject = sceneInstance:GetCacheObjectByName("Main Camera")
        KTool.GetOrAddComponent(cameraObject, typeof(URPBaseCamera))
        SceneManagementIns:SetActive(SceneId, true)

        blocker:AddCondition("CatHouseCatCheckPopup")
        cs_coroutine.start(function()
            self:FreshUI()

            local abs = math.abs
            self.TouchRegion.onSingleFingerDrag:AddListener(function(delta)
                if isNull(self.go) then return end
                local y = delta.y
                local x = delta.x
                if abs(x) < abs(y) then
                    return
                end
                local direction = x < 0 and 1 or -1
                local eulerAngles = Vector3.New(0, 1, 0)
                eulerAngles.y = eulerAngles.y * direction * abs(x)
                self.go.transform:Rotate(eulerAngles)
            end)
            blocker:RemoveCondition("CatHouseCatCheckPopup")
        end)

    end))
    return coWait
end

function CatHouseCatCheckPopup:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshCatDataInfo(self.catData)
        self:FreshPriceUI()
    end))
    return coWait
end

function CatHouseCatCheckPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

