function CatHouseCatCheckPopup:FreshUI()
    self:LoadCat()
end

function CatHouseCatCheckPopup:LoadCat()
    xTry(function ()
        local catData = self.catData
        local catHouseMgr = CatHouseMgr:GetInstance()
        local age = catData.age
        catHouseMgr:LoadCatModelAsync(catData.age, catData.catId, false, catHouseMgr:GetAttributes(catData.genes), nil, function(go)
            ---@type UnityEngine.Transform
            local transform = go.transform
            transform.localScale = Vector3.one
            transform.position = Vector3.New(0, 0.034, 0)
            transform.localRotation = age == ConstantsCatHouse.BornType.Adult and CatModelLocalRotation.Adult or CatModelLocalRotation.Child
            self.go = go
        end)
        
    end)
end

function CatHouseCatCheckPopup:FreshCatDataInfo(catData)
    ---@type CatHouseCatDataInfo
    local env = CfUtils.GetLuaScr(self.LeftPanel, CatHouseCatDataInfoEnvPath)
    if isNull(env) then return end
    env:FreshUI(catData)
end

function CatHouseCatCheckPopup:FreshPriceUI()
    local viewType    = self.viewType
    local isShowPrice = viewType == ViewType.Rally
    KTool.SetActive(self.Price.gameObject, isShowPrice)
    if isShowPrice then
        local price = self.catData.price
        self.TextNumber.text = price
        local rallyGoodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetGoodsVoById(rallyGoodsId)
        self.ImgIcon:LoadSprite(goodsVo.photoPath)
    end
end

