function CatHouseCatCheckPopup:OnClickCultivationBtnAction()
    local catData = self.catData
    if catData.age == ConstantsCatHouse.BornType.Baby then
        GameUtils.Toast(localize("幼年期不能培育"))
        return
    end
    blocker:AddCondition("CatHouseCatCheckPopup")
    cs_coroutine.start(function()
        --- 保存配对界面所需数据
        if self.viewType == ViewType.Rally then
            KCookie.Set(CookieOtherCatInfoName, {otherCatData = catData, otherCatOwnerInfo = {playerId = catData.playerId}, consumePrice = catData.price, matchType = 3})
        elseif self.viewType == ViewType.ChooseFriend then
            KCookie.Set(CookieOtherCatInfoName, {otherCatData = catData, otherCatOwnerInfo = self.playerData, matchType = 1})
        end
        if self.extraParams and checkNumber(self.extraParams.geneId) > 0 then
            local isOwnGeneId = checkNumber(self.extraParams.geneId) > 0
            ---因为猫屋主界面常驻 所以 如果想清除记录的话必须移动记录到 UIHomeView
            local needRemoveRecordId = isOwnGeneId and Constants.UITypeIds.UIHomeView or nil
            CatHouseMgr:GetInstance():BackToMatchPopup(isOwnGeneId, isOwnGeneId, false, nil, needRemoveRecordId)
        else
            --- 关闭当前界面
            cs_coroutine.yield_return(UIModule.BackDialog())
            KCookie.Set(CookieCultivationResetCameraEnter, 1)
            --- 关闭列表界面
            cs_coroutine.yield_return(UIModule.BackDialog())
        end
        blocker:RemoveCondition("CatHouseCatCheckPopup")

    end)
end

